  const cls = v => /^(yes|✓|ok|safe|prevented|strong)\b/i.test(v) ? 'y' : /^(no|✗|unsafe|possible|weak)\b/i.test(v) ? 'n' : /^(partial|~|maybe|some|depends|sometimes)\b/i.test(v) ? 'p' : '';
